using System;
using System.IO;
using System.Text;
using System.Diagnostics;
using System.Collections.Generic;
using System.Threading;
public static class MsvcHostRustcWrapper {
 const string Bin=@"D:\project\dlpad\.local-tools\windows\rust\bin";
 static void Require(bool yes){if(!yes)throw new InvalidDataException("wrapper_contract_rejected");}
 static string Compiler(string p){Require(Path.IsPathRooted(p)&&p.Length<=32767&&p.IndexOf('\0')<0);foreach(string part in p.Replace('/','\\').Split('\\'))Require(part!=".."&&part!=".");string full=Path.GetFullPath(p);string leaf=Path.GetFileName(full);Require((leaf.Equals("rustc.exe",StringComparison.OrdinalIgnoreCase)||leaf.Equals("clippy-driver.exe",StringComparison.OrdinalIgnoreCase))&&Path.GetDirectoryName(full).Equals(Bin,StringComparison.OrdinalIgnoreCase));for(string q=full;q!=null;q=Path.GetDirectoryName(q))Require((File.GetAttributes(q)&FileAttributes.ReparsePoint)==0);return full;}
 static string Quote(string value){Require(value.Length<=32767&&value.IndexOf('\0')<0);var b=new StringBuilder("\"");int slash=0;foreach(char c in value){if(c=='\\'){slash++;continue;}b.Append('\\',c=='"'?slash*2+1:slash);b.Append(c);slash=0;}b.Append('\\',slash*2);return b.Append('"').ToString();}
 // Pure policy helper is the production dispatch path, not a duplicate implementation.
 public static string[] Transform(string[] args,out string mode){Require(args.Length>=1&&args.Length<=4096);Compiler(args[0]);int first=1;if(Path.GetFileName(args[0]).Equals("clippy-driver.exe",StringComparison.OrdinalIgnoreCase)&&args.Length>1&&!args[1].StartsWith("-",StringComparison.Ordinal)){Compiler(args[1]);Require(Path.GetFileName(args[1]).Equals("rustc.exe",StringComparison.OrdinalIgnoreCase));first=2;}
  string target=null;bool query=false;int characters=0;for(int i=first;i<args.Length;i++){string a=args[i];Require(a!=null&&a.IndexOf('\0')<0);characters=checked(characters+a.Length);Require(characters<=120000);if(a=="--target"){Require(target==null&&i+1<args.Length);target=args[++i];Require(!target.StartsWith("-",StringComparison.Ordinal));}else if(a.StartsWith("--target=",StringComparison.Ordinal)){Require(target==null);target=a.Substring(9);}else if(a.StartsWith("--target",StringComparison.Ordinal))Require(false);if(a=="--version"||a=="-V"||a=="-vV"||a=="--help"||a=="-h"||a=="--print"||a.StartsWith("--print=",StringComparison.Ordinal))query=true;}
  Require(target==null||target=="x86_64-pc-windows-gnu"||target=="x86_64-pc-windows-msvc");bool host=target==null||target=="x86_64-pc-windows-gnu";mode=query?"query-unchanged":host?"gnu-host-self-contained":"msvc-target-unchanged";var result=new List<string>();for(int i=1;i<args.Length;i++)result.Add(args[i]);if(host&&!query){result.Add("-C");result.Add("link-self-contained=yes");}return result.ToArray();}
 sealed class Pump {public Exception error;public Thread thread;public long bytes;public void Start(Stream source,Stream destination){thread=new Thread(delegate(){try{byte[] buffer=new byte[65536];int n;while((n=source.Read(buffer,0,buffer.Length))>0){Require(bytes+n<=8388608);bytes+=n;destination.Write(buffer,0,n);destination.Flush();}}catch(Exception e){error=e;}finally{try{source.Dispose();}catch(Exception e){if(error==null)error=e;}}});thread.IsBackground=true;thread.Start();}}
 public static int Main(string[] args){try{string mode;var forwarded=Transform(args,out mode);Require(Array.IndexOf(forwarded,"-")<0||mode=="query-unchanged");string compiler=Compiler(args[0]);using(var pin=new FileStream(compiler,FileMode.Open,FileAccess.Read,FileShare.Read)){Require(pin.Length>0&&pin.Length<=268435456);FileStream nested=null;try{if(Path.GetFileName(compiler).Equals("clippy-driver.exe",StringComparison.OrdinalIgnoreCase)&&forwarded.Length>0&&!forwarded[0].StartsWith("-",StringComparison.Ordinal))nested=new FileStream(Compiler(forwarded[0]),FileMode.Open,FileAccess.Read,FileShare.Read);var command=new StringBuilder();foreach(string a in forwarded){if(command.Length>0)command.Append(' ');command.Append(Quote(a));}Require(command.Length<=32767);var info=new ProcessStartInfo(compiler,command.ToString());info.UseShellExecute=false;info.CreateNoWindow=true;info.RedirectStandardOutput=true;info.RedirectStandardError=true;info.RedirectStandardInput=true;
    // No text decoder: compiler bytes are forwarded unchanged to Cargo capture handles.
    if(Environment.GetEnvironmentVariable("DLPAD_MSVC_WRAPPER_TRACE")=="1")Console.Error.WriteLine("dlpad-msvc-rustc-wrapper mode="+mode);
    using(var child=Process.Start(info)){Require(child!=null);child.StandardInput.Close();var stdout=new Pump();var stderr=new Pump();stdout.Start(child.StandardOutput.BaseStream,Console.OpenStandardOutput());stderr.Start(child.StandardError.BaseStream,Console.OpenStandardError());child.WaitForExit();bool outputDone=stdout.thread.Join(5000);bool errorDone=stderr.thread.Join(5000);Require(outputDone&&errorDone&&stdout.error==null&&stderr.error==null);return child.ExitCode;}
   }finally{if(nested!=null)nested.Dispose();}}
  }catch(Exception){try{Console.Error.WriteLine("dlpad-msvc-rustc-wrapper rejected");}catch{}return 125;}}
}
